// ValidateOrganizationHierarchyView runs the validations defined on
// OrganizationHierarchyView using the "default" view.
func ValidateOrganizationHierarchyView(result *OrganizationHierarchyView) (err error) {
	if result.Root == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("root", "result"))
	}
	if result.Children == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("children", "result"))
	}
	if result.Ancestors == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("ancestors", "result"))
	}
	if result.Depth == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("depth", "result"))
	}
	if result.Root != nil {
		if err2 := ValidateOrganizationNodeView(result.Root); err2 != nil {
			err = goa.MergeErrors(err, err2)
		}
	}
	for _, e := range result.Children {
		if e != nil {
			if err2 := ValidateOrganizationNodeView(e); err2 != nil {
				err = goa.MergeErrors(err, err2)
			}
		}
	}
	for _, e := range result.Ancestors {
		if e != nil {
			if err2 := ValidateOrganizationNodeView(e); err2 != nil {
				err = goa.MergeErrors(err, err2)
			}
		}
	}
	return
}

// ValidateOrganizationNodeView runs the validations defined on
// OrganizationNodeView.
func ValidateOrganizationNodeView(result *OrganizationNodeView) (err error) {
	if result.ID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("id", "result"))
	}
	if result.Name == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("name", "result"))
	}
	if result.OrganizationType == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("organization_type", "result"))
	}
	if result.Status == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("status", "result"))
	}
	if result.Children == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("children", "result"))
	}
	if result.Level == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("level", "result"))
	}
	if result.ID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("result.id", *result.ID, goa.FormatUUID))
	}
	if result.Name != nil {
		if utf8.RuneCountInString(*result.Name) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("result.name", *result.Name, utf8.RuneCountInString(*result.Name), 1, true))
		}
	}
	if result.Name != nil {
		if utf8.RuneCountInString(*result.Name) > 200 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("result.name", *result.Name, utf8.RuneCountInString(*result.Name), 200, false))
		}
	}
	if result.OrganizationType != nil {
		if !(*result.OrganizationType == "CORPORATION" || *result.OrganizationType == "LLC" || *result.OrganizationType == "PARTNERSHIP" || *result.OrganizationType == "SOLE_PROPRIETORSHIP" || *result.OrganizationType == "NON_PROFIT" || *result.OrganizationType == "GOVERNMENT") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("result.organization_type", *result.OrganizationType, []any{"CORPORATION", "LLC", "PARTNERSHIP", "SOLE_PROPRIETORSHIP", "NON_PROFIT", "GOVERNMENT"}))
		}
	}
	if result.Status != nil {
		if !(*result.Status == "ACTIVE" || *result.Status == "INACTIVE" || *result.Status == "SUSPENDED" || *result.Status == "DISSOLVED") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("result.status", *result.Status, []any{"ACTIVE", "INACTIVE", "SUSPENDED", "DISSOLVED"}))
		}
	}
	return
}
